function cpy(){var t=fm();try{return navigator.clipboard.writeText(t)}catch(x){return Promise.reject()}}
function chat(u,same){cpy().then(function(){$('fs').textContent='Your request is copied. Paste it in the chat.'},function(){$('fs').textContent='Opening the chat. Please type your request there.'});if(same)location.href=u;else window.open(u,'_blank','noopener')}
